mapper.select:
        SELECT item_id, item_name, category_id, location, occur_date, unique_mark, description, image_url, user_id, publish_time, poster_whatsapp, status,intent
        FROM item t
        
            
            AND t.status = 'approved'

            
            AND NOT EXISTS (
            SELECT 1 FROM claim c
            WHERE c.item_id = t.item_id AND c.status = 'approved'
            )

            
                AND t.item_name LIKE CONCAT('%', #{itemName}, '%')
            
            
                AND t.category_id = #{category}
            
            
                AND t.intent = #{intent}
            
            
                AND t.location = #{location}
            
        
        
            ORDER BY t.publish_time DESC
        
        
            ORDER BY t.publish_time ASC

mapper.update:
UPDATE item
SET status = #{status}
WHERE item_id = #{itemId}
